function createAlignmentTable(alignment) {
	var table = d3.select('body').append('table')
	var thead = table.append('thead')
	var	tbody = table.append('tbody');

	var header = ['label', 'sequence'];

	// append the header row
	thead.append('tr')
	  .selectAll('th')
	  .data(header).enter()
	  .append('th')
	    .text(function (column) { return column; });

	// create a row for each object in the data
	var rows = tbody.selectAll('tr')
	  .data(alignment)
	  .enter()
	  .append('tr');

	// create a cell in each row for each column
	var cells = rows.selectAll('td')
	  .data(function (row) {
	    return columns.map(function (column) {
	      return {column: column, value: row[column]};
	    });
	  })
	  .enter()
	  .append('td')
	    .text(function (d) { return d.value; });

  return table;
}

// Wire toolbar controls to the SealionViewer API (safe no-ops if viewer absent)
;(function wireToolbar(){
	function byId(id){ try{ return document.getElementById(id); }catch(_){ return null; } }
	const incBtn = byId('font-increase-btn');
	const decBtn = byId('font-decrease-btn');
	const maskBtn = byId('apply-constant-mask-btn');
	const maskAmbBtn = byId('apply-constant-ambiguous-btn');
	const maskGappedBtn = byId('apply-constant-gapped-btn');
	const refToggle = byId('ref-toggle');
	const setRefBtn = byId('set-ref-btn');
	const diffConsBtn = byId('diff-consensus-btn');
	const snapToggle = byId('snap-toggle');
	const searchInput = byId('search-input');
	const searchNext = byId('search-next');

	function safeViewer(){ return (window && window.viewer) ? window.viewer : null; }

	function getMaxSeqLen(){
		const lens = alignment && alignment.length ? alignment.map(function(a){ return (a.sequence||'').length; }) : [];
		return lens.length ? Math.max.apply(null, lens) : 0;
	}

	if(incBtn){
		incBtn.addEventListener('click', function(){
			try{
				const v = safeViewer();
				const cur = (window && window.FONT) ? window.FONT : '12px monospace';
				const m = String(cur).match(/(\d+)px/);
				const px = m ? parseInt(m[1],10) : 12;
				const next = Math.min(36, px + 1);
				window.FONT = String(cur).replace(/(\d+)px/, next + 'px');
				if(v && typeof v.measureCharWidth === 'function'){
					const maxSeqLen = getMaxSeqLen();
					try{ v.measureCharWidth(window.FONT, { apply: true, maxSeqLen: maxSeqLen }); }catch(_){ }
					try{ v.measureRowHeightFromFonts({ FONT: window.FONT, apply: true }); }catch(_){ }
				}
			}catch(e){ console.warn('font-increase failed', e); }
		});
	}

	if(decBtn){
		decBtn.addEventListener('click', function(){
			try{
				const v = safeViewer();
				const cur = (window && window.FONT) ? window.FONT : '12px monospace';
				const m = String(cur).match(/(\d+)px/);
				const px = m ? parseInt(m[1],10) : 12;
				const next = Math.max(6, px - 1);
				window.FONT = String(cur).replace(/(\d+)px/, next + 'px');
				if(v && typeof v.measureCharWidth === 'function'){
					const maxSeqLen = getMaxSeqLen();
					try{ v.measureCharWidth(window.FONT, { apply: true, maxSeqLen: maxSeqLen }); }catch(_){ }
					try{ v.measureRowHeightFromFonts({ FONT: window.FONT, apply: true }); }catch(_){ }
				}
			}catch(e){ console.warn('font-decrease failed', e); }
		});
	}

	if(maskBtn){
		maskBtn.addEventListener('click', function(){
			try{
				const v = safeViewer(); if(!v) return;
				const mask = (typeof v.computeConstantMask === 'function') ? v.computeConstantMask() : null;
				if(mask){
					v.maskStr = mask;
					v.maskEnabled = true;
					try{ v.buildColOffsetsFor(true, { maxSeqLen: getMaxSeqLen(), CHAR_WIDTH: v.charWidth }); }catch(_){ }
					try{ v.scheduleRender(); }catch(_){ }
				}
			}catch(e){ console.warn('apply-constant-mask failed', e); }
		});
	}

	if(maskAmbBtn){
		maskAmbBtn.addEventListener('click', function(){
			try{
				const v = safeViewer(); if(!v) return;
				const mask = (typeof v.computeConstantMaskAllowN === 'function') ? v.computeConstantMaskAllowN() : null;
				if(mask){
					v.maskStr = mask;
					v.maskEnabled = true;
					try{ v.buildColOffsetsFor(true, { maxSeqLen: getMaxSeqLen(), CHAR_WIDTH: v.charWidth }); }catch(_){ }
					try{ v.scheduleRender(); }catch(_){ }
				}
			}catch(e){ console.warn('apply-constant-ambiguous failed', e); }
		});
	}

	if(maskGappedBtn){
		maskGappedBtn.addEventListener('click', function(){
			try{
				const v = safeViewer(); if(!v) return;
				const mask = (typeof v.computeConstantMaskAllowNAndGaps === 'function') ? v.computeConstantMaskAllowNAndGaps() : null;
				if(mask){
					v.maskStr = mask;
					v.maskEnabled = true;
					try{ v.buildColOffsetsFor(true, { maxSeqLen: getMaxSeqLen(), CHAR_WIDTH: v.charWidth }); }catch(_){ }
					try{ v.scheduleRender(); }catch(_){ }
				}
			}catch(e){ console.warn('apply-constant-gapped failed', e); }
		});
	}

	if(refToggle){
		refToggle.addEventListener('change', function(){
			try{ const v = safeViewer(); if(!v) return; v.refModeEnabled = !!this.checked; try{ v.scheduleRender(); }catch(_){ } }catch(e){ console.warn('ref-toggle failed', e); }
		});
	}

	if(setRefBtn){
		setRefBtn.addEventListener('click', function(){
			try{
				const v = safeViewer(); if(!v) return;
				const sel = (v.getSelectedRows && typeof v.getSelectedRows === 'function') ? Array.from(v.getSelectedRows()) : [];
				if(sel && sel.length){ v.refIndex = sel[0]; try{ v.scheduleRender(); }catch(_){ } }
			}catch(e){ console.warn('set-ref failed', e); }
		});
	}

	if(diffConsBtn){
		diffConsBtn.addEventListener('click', function(){
			try{
				const v = safeViewer(); if(!v) return;
				const cons = (v.computeConsensusSequence && typeof v.computeConsensusSequence === 'function') ? v.computeConsensusSequence() : null;
				if(cons){ window.refStr = cons; v.refModeEnabled = true; try{ v.scheduleRender(); }catch(_){ } }
			}catch(e){ console.warn('diff-consensus failed', e); }
		});
	}

	if(snapToggle){
		snapToggle.addEventListener('change', function(){ try{ const v = safeViewer(); if(!v) return; v.snapEnabled = !!this.checked; }catch(e){ console.warn('snap-toggle failed', e); } });
	}

	if(searchNext && searchInput){
		let lastMatches = [];
		let idx = 0;
		searchNext.addEventListener('click', function(){
			try{
				const v = safeViewer(); if(!v) return;
				const q = searchInput.value || '';
				if(!q) return;
				if(!lastMatches || lastMatches.query !== q){ lastMatches = v.findMatches(q) || []; lastMatches.query = q; idx = 0; }
				if(lastMatches && lastMatches.length){
					const row = lastMatches[idx % lastMatches.length];
					if(v.setSelectedRows) v.setSelectedRows(new Set([row]));
					const ROW_HEIGHT = (window && typeof window.ROW_HEIGHT === 'number') ? window.ROW_HEIGHT : (v.ROW_HEIGHT || 20);
					const targetTop = Math.max(0, row * ROW_HEIGHT - Math.floor((v.scroller ? v.scroller.clientHeight : window.innerHeight)/2));
					if(v.animateScrollTo){ try{ v.animateScrollTo(null, targetTop, v.scroller); }catch(_){ if(v.scroller) v.scroller.scrollTop = targetTop; } }
					else if(v.scroller) v.scroller.scrollTop = targetTop;
					try{ if(v.scheduleRender) v.scheduleRender(); }catch(_){ }
					idx = (idx + 1) % Math.max(1, lastMatches.length);
				}
			}catch(e){ console.warn('search-next failed', e); }
		});
	}

})();


// Prefer the new SealionViewer if it's present. Only run the legacy
// createAlignmentTable fallback when SealionViewer is not available.
// This avoids a premature legacy render that can race with the viewer's
// initialization (which was observed to publish too-small colOffsets).
if (window.SealionViewer) {
	// SealionViewer is available — initialize it so the new viewer appears
	// immediately. If initialization fails, fall back to the legacy table.
	console.log('script.js: SealionViewer detected — initializing viewer');
	try {
		// Construct the viewer inside the `#sealion` container we added in index.html.
		// The constructor will create missing canvases and DOM structure as needed.
		window.viewer = new window.SealionViewer('#sealion', alignment, {});

		// Attach default interaction handlers to the canvases the viewer created.
		try{
			window.viewer.attachInteractionHandlers({
				headerCanvas: window.viewer.headerCanvas,
				seqCanvas: window.viewer.seqCanvas,
				labelCanvas: window.viewer.labelCanvas,
				consensusCanvas: window.viewer.consensusCanvas,
				overviewCanvas: window.viewer.overviewCanvas,
				scroller: window.viewer.scroller
			});
		}catch(_){ }

		// Build colOffsets with a reliable maxSeqLen so the first render has
		// the full offsets array (avoids the observed length==1 race).
		try{
			if(typeof window.viewer.buildColOffsetsFor === 'function'){
				var lens = alignment && alignment.length ? alignment.map(function(a){ return (a.sequence||'').length; }) : [];
				var maxSeqLen = lens.length ? Math.max.apply(null, lens) : 0;
				try{ window.viewer.buildColOffsetsFor(!!window.viewer.maskEnabled, { maxSeqLen: maxSeqLen, CHAR_WIDTH: window.viewer.charWidth }); }catch(_){ }
			}
		}catch(_){ }

		// Schedule an initial render
		try{ if(window.viewer && typeof window.viewer.scheduleRender === 'function') window.viewer.scheduleRender(); }catch(_){ }

		// Update toolbar status if present
		try{ var st = document.getElementById('viewer-status'); if(st) st.textContent = 'Viewer ready'; }catch(_){ }

	} catch (e) {
		console.error('script.js: SealionViewer initialization failed, falling back to legacy table', e);
		// fallback to legacy table if viewer init failed
		if (document.readyState === 'loading') {
			document.addEventListener('DOMContentLoaded', function () { createAlignmentTable(alignment); });
		} else {
			createAlignmentTable(alignment);
		}
	}
} else {
	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', function () { createAlignmentTable(alignment); });
	} else {
		createAlignmentTable(alignment);
	}
}